from typing import List

def parse_music(music_string: str) -> List[int]:
    notes_dict = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split()
    beats_list = [notes_dict[note] for note in notes]

    return beats_list

